// Replays the replication conformance vectors (vectors/replication/*.trace,
// generated by orderer-rust's simulator) against Node in src/consensus.ts.
// Every effect and state line must match exactly.
//
//   node dist/tests/replication.js [vectors-dir]
import * as fs from "fs";
import * as path from "path";
import { Config, Disk, Effect, Entry, Msg, NONE, Node } from "../src/consensus";
import { check, lines, runAll, slurp } from "./t";

const VEC = process.argv[2] ?? "vectors";

const hexs = (d: Uint8Array) => (d.length === 0 ? "-" : Buffer.from(d).toString("hex"));
const unhex = (s: string) => (s === "-" ? new Uint8Array(0) : new Uint8Array(Buffer.from(s, "hex")));
const fmtEntry = (e: Entry) => `${e.term}:${hexs(e.data)}`;
const fmtEntries = (es: Entry[]) => (es.length === 0 ? "-" : es.map(fmtEntry).join(","));
const parseEntries = (s: string): Entry[] =>
  s === "-" ? [] : s.split(",").map((p) => {
    const c = p.indexOf(":");
    return { term: Number(p.slice(0, c)), data: unhex(p.slice(c + 1)) };
  });
const b = (x: boolean) => (x ? 1 : 0);

function fmtMsg(m: Msg): string {
  switch (m.kind) {
    case "vote": return `vote ${m.term} ${m.lastIndex} ${m.lastTerm} ${b(m.pre)}`;
    case "votereply": return `votereply ${m.term} ${b(m.granted)} ${b(m.pre)}`;
    case "append": return `append ${m.term} ${m.prevIndex} ${m.prevTerm} ${m.commit} ${fmtEntries(m.entries)}`;
    case "appendreply": return `appendreply ${m.term} ${b(m.success)} ${m.index}`;
  }
}

function parseMsg(w: string[]): Msg {
  const n = (i: number) => Number(w[i]);
  switch (w[0]) {
    case "vote": return { kind: "vote", term: n(1), lastIndex: n(2), lastTerm: n(3), pre: n(4) === 1 };
    case "votereply": return { kind: "votereply", term: n(1), granted: n(2) === 1, pre: n(3) === 1 };
    case "append": return { kind: "append", term: n(1), prevIndex: n(2), prevTerm: n(3), commit: n(4), entries: parseEntries(w[5]) };
    case "appendreply": return { kind: "appendreply", term: n(1), success: n(2) === 1, index: n(3) };
  }
  throw new Error(`unknown message ${w[0]}`);
}

function fmtEffect(e: Effect): string {
  switch (e.kind) {
    case "send": return `send ${e.to} ${fmtMsg(e.msg)}`;
    case "persist": {
      const p = e.persist;
      return `persist ${p.token} ${p.term} ${p.votedFor === NONE ? "-" : p.votedFor} ${p.from} ${p.compact ? `${p.compact.index}:${p.compact.term}` : "-"} ${fmtEntries(p.entries)}`;
    }
    case "apply": return `apply ${e.index} ${fmtEntry(e.entry)}`;
    case "needsnap": return `needsnap ${e.to} ${e.index} ${e.term}`;
    case "restore": return `restore ${e.index} ${e.term}`;
  }
}

const fmtState = (n: Node) =>
  `state role=${n.role} term=${n.term} leader=${n.leader === NONE ? "-" : n.leader} commit=${n.commitIndex} applied=${n.appliedIndex} base=${n.base} last=${n.lastIndex}`;

function field(line: string, key: string): string {
  for (const w of line.trim().split(/\s+/)) if (w.startsWith(`${key}=`)) return w.slice(key.length + 1);
  throw new Error(`missing ${key}`);
}

function parseNode(line: string): Node {
  const peers = field(line, "peers").split(",").map(Number);
  const cfg: Config = {
    electionTicks: Number(field(line, "election")),
    heartbeatTicks: Number(field(line, "heartbeat")),
    maxBatch: Number(field(line, "batch")),
    preVote: field(line, "prevote") === "1",
  };
  const d = field(line, "disk").split(":");
  const disk: Disk = {
    term: Number(d[0]),
    votedFor: d[1] === "-" ? NONE : Number(d[1]),
    base: Number(d[2]),
    baseTerm: Number(d[3]),
    log: parseEntries(d.slice(4).join(":")),
  };
  return new Node(Number(field(line, "id")), peers, cfg, BigInt(field(line, "seed")), disk);
}

function replay(name: string, text: string): number {
  let node: Node | undefined;
  let expected: string[] = [];
  let checked = 0;
  let ln = 0;
  for (const line of lines(text)) {
    ln++;
    const w = line.trim().split(/\s+/);
    if (w[0] === "") continue;
    if (w[0] === "node") node = parseNode(line);
    else if (w[0] === "in") {
      switch (w[1]) {
        case "tick": node!.tick(); break;
        case "step": node!.step(Number(w[2]), parseMsg(w.slice(3))); break;
        case "propose": node!.propose(unhex(w[2])); break;
        case "replicate": node!.replicate(); break;
        case "persisted": node!.persisted(Number(w[2])); break;
        case "compact": node!.compact(Number(w[2])); break;
        case "install": node!.installSnapshot(Number(w[2]), Number(w[3]), Number(w[4]), Number(w[5])); break;
        default: throw new Error(`${name}:${ln}: unknown input ${w[1]}`);
      }
    } else if (w[0] === "out" || w[0] === "state") {
      expected.push(line);
      if (w[0] === "state") {
        const got = node!.takeEffects().map((e) => `out ${fmtEffect(e)}`);
        got.push(fmtState(node!));
        if (got.join("\n") !== expected.join("\n")) {
          let i = 0;
          while (i < got.length && i < expected.length && got[i] === expected[i]) i++;
          check(false, `${name}:${ln}: output differs at item ${i}\n  want: ${expected[i] ?? "<end>"}\n  got:  ${got[i] ?? "<end>"}`);
          return checked;
        }
        checked++;
        expected = [];
      }
    } else if (w[0] !== "#") throw new Error(`${name}:${ln}: unknown line kind ${w[0]}`);
  }
  return checked;
}

runAll([
  ["replication_conformance_vectors", () => {
    const dir = path.join(VEC, "replication");
    const files = fs.readdirSync(dir).filter((f) => f.endsWith(".trace")).sort();
    check(files.length > 0, `no traces in ${dir}`);
    let total = 0;
    for (const f of files) {
      const n = replay(f, slurp(path.join(dir, f)));
      check(n > 100, `${f}: only ${n} checked steps`);
      total += n;
    }
    console.log(`  replayed ${files.length} traces, ${total} drain points`);
  }],
]);
